import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterModule } from '@angular/router';
import { AuthService, RegisterRequest } from '../../services/auth.service';

@Component({
  selector: 'app-register',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterModule],
  templateUrl: './register.component.html',
  styleUrls: ['./register.component.css']
})
export class RegisterComponent {
  userData: RegisterRequest = {
    username: '',
    email: '',
    password: ''
  };

  loading = false;
  error: string | null = null;
  showPassword = false;

  constructor(
    private authService: AuthService,
    private router: Router
  ) {}

  onSubmit(): void {
    if (!this.validateForm()) {
      return;
    }

    this.loading = true;
    this.error = null;

    this.authService.register(this.userData).subscribe({
      next: (response) => {
        this.loading = false;
        this.router.navigate(['/trips']);
      },
      error: (error) => {
        this.loading = false;
        this.error = error.error?.message || 'Registration failed. Please try again.';
        console.error('Registration error:', error);
      }
    });
  }

  validateForm(): boolean {
    if (!this.userData.username?.trim()) {
      this.error = 'Username is required';
      return false;
    }

    if (!this.userData.email?.trim()) {
      this.error = 'Email is required';
      return false;
    }

    if (!this.isValidEmail(this.userData.email)) {
      this.error = 'Please enter a valid email address';
      return false;
    }

    if (!this.userData.password?.trim()) {
      this.error = 'Password is required';
      return false;
    }

    if (this.userData.password.length < 6) {
      this.error = 'Password must be at least 6 characters long';
      return false;
    }

    this.error = null;
    return true;
  }

  isValidEmail(email: string): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }

  togglePasswordVisibility(): void {
    this.showPassword = !this.showPassword;
  }

  clearForm(): void {
    this.userData = {
      username: '',
      email: '',
      password: ''
    };
    this.error = null;
  }
}

<div class="register-container">
  <div class="container">
    <div class="row justify-content-center align-items-center min-vh-100">
      <div class="col-lg-5 col-md-7 col-sm-9">
        <!-- Register Card -->
        <div class="card shadow-lg border-0 register-card">
          <!-- Header -->
          <div class="card-header text-center bg-success text-white">
            <div class="register-header">
              <i class="fas fa-user-plus fa-3x mb-3"></i>
              <h2 class="fw-bold mb-1">Create Account</h2>
              <p class="mb-0 opacity-75">Join Travlr Admin Panel</p>
            </div>
          </div>

          <!-- Body -->
          <div class="card-body p-4">
            <!-- Error Message -->
            <div *ngIf="error" class="alert alert-danger alert-dismissible fade show" role="alert">
              <i class="fas fa-exclamation-triangle me-2"></i>{{ error }}
              <button type="button" class="btn-close" (click)="error = null"></button>
            </div>

            <!-- Register Form -->
            <form (ngSubmit)="onSubmit()" #registerForm="ngForm" novalidate>
              <!-- Username Field -->
              <div class="mb-3">
                <label for="username" class="form-label fw-semibold">
                  <i class="fas fa-user me-1"></i>Username
                </label>
                <input
                  type="text"
                  class="form-control form-control-lg"
                  id="username"
                  name="username"
                  [(ngModel)]="userData.username"
                  placeholder="Enter your username"
                  autocomplete="username"
                  required>
              </div>

              <!-- Email Field -->
              <div class="mb-3">
                <label for="email" class="form-label fw-semibold">
                  <i class="fas fa-envelope me-1"></i>Email Address
                </label>
                <input
                  type="email"
                  class="form-control form-control-lg"
                  id="email"
                  name="email"
                  [(ngModel)]="userData.email"
                  placeholder="Enter your email"
                  autocomplete="email"
                  required>
              </div>

              <!-- Password Field -->
              <div class="mb-4">
                <label for="password" class="form-label fw-semibold">
                  <i class="fas fa-lock me-1"></i>Password
                </label>
                <div class="input-group">
                  <input
                    [type]="showPassword ? 'text' : 'password'"
                    class="form-control form-control-lg"
                    id="password"
                    name="password"
                    [(ngModel)]="userData.password"
                    placeholder="Enter your password"
                    autocomplete="new-password"
                    required>
                  <button
                    type="button"
                    class="btn btn-outline-secondary"
                    (click)="togglePasswordVisibility()"
                    [disabled]="loading">
                    <i [class]="showPassword ? 'fas fa-eye-slash' : 'fas fa-eye'"></i>
                  </button>
                </div>
              </div>

              <!-- Submit Button -->
              <div class="d-grid gap-2 mb-3">
                <button
                  type="submit"
                  class="btn btn-success btn-lg"
                  [disabled]="loading || !registerForm.form.valid">
                  <span *ngIf="loading" class="spinner-border spinner-border-sm me-2"></span>
                  <i *ngIf="!loading" class="fas fa-user-plus me-2"></i>
                  {{ loading ? 'Creating Account...' : 'Create Account' }}
                </button>
              </div>

              <!-- Clear Form Button -->
              <div class="d-grid">
                <button
                  type="button"
                  class="btn btn-outline-secondary"
                  (click)="clearForm()"
                  [disabled]="loading">
                  <i class="fas fa-eraser me-2"></i>Clear Form
                </button>
              </div>
            </form>
          </div>

          <!-- Footer -->
          <div class="card-footer bg-light text-center">
            <small class="text-muted">
              Already have an account? 
              <a routerLink="/login" class="text-decoration-none">
                <i class="fas fa-sign-in-alt me-1"></i>Sign in here
              </a>
            </small>
          </div>
        </div>
      </div>
    </div>
  </div>
</div>
